  { auto _e = coupon_rule(); if (_e) { if(_o->coupon_rule) { _e->UnPackTo(_o->coupon_rule.get(), _resolver); } else { _o->coupon_rule = std::unique_ptr<quantra::CouponRuleT>(_e->UnPack(_resolver)); } } else if (_o->coupon_rule) { _o->coupon_rule.reset(); } }
