  { auto _e = maturity_payment_date(); if (_e) _o->maturity_payment_date = _e->str(); }
  { auto _e = discounting_curve(); if (_e) _o->discounting_curve = _e->str(); }
  { auto _e = funding_spread_bp(); _o->funding_spread_bp = _e; }
